import sys
from rich.traceback import Traceback

def test_notes():
    try:
        try:
            raise ValueError("Original Error")
        except ValueError as e:
            e.__notes__ = "Some helpful notes"
            raise e
    except ValueError as e:
        exc_type, exc_value, tb_obj = sys.exc_info()
        trace = Traceback.extract(exc_type, exc_value, tb_obj)
        # The trace object contains a list of stacks
        assert trace.stacks[-1].notes == "Some helpful notes", f"Expected 'Some helpful notes', got {trace.stacks[-1].notes}"

if __name__ == "__main__":
    test_notes()
    print("Success")
